source='''from collections import Counter, deque


def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            comps.append((color, cells))
    return comps


def _canonical(cells):
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    pts = [(r-r0, c-c0) for r, c in cells]
    forms = []
    for flip in (1, -1):
        for rot in range(4):
            transformed = []
            for r, c in pts:
                x, y = r, c * flip
                for _ in range(rot):
                    x, y = y, -x
                transformed.append((x, y))
            a = min(x for x, y in transformed)
            b = min(y for x, y in transformed)
            forms.append(tuple(sorted((x-a, y-b) for x, y in transformed)))
    return min(forms)


def _find_l(comp):
    color, cells = comp
    rows = Counter(r for r, c in cells)
    cols = Counter(c for r, c in cells)
    # A marker L has a long complete horizontal and vertical arm.
    for r, nr in rows.most_common():
        for c, nc in cols.most_common():
            if nr < 3 or nc < 3 or (r, c) not in cells:
                continue
            if all((r, x) in cells for x in range(min(x for y, x in cells), max(x for y, x in cells)+1)) and all((y, c) in cells for y in range(min(y for y, x in cells), max(y for y, x in cells)+1)):
                # The corner is an end of both arms; reject a cross or filled block.
                rs = sorted({y for y, x in cells if x == c})
                cs = sorted({x for y, x in cells if y == r})
                vr = -1 if rs[-1] == r else (1 if rs[0] == r else 0)
                hc = -1 if cs[-1] == c else (1 if cs[0] == c else 0)
                if vr and hc and len(cells) <= nr + nc:
                    return (r, c, vr, hc)
    return None


def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, background)
    markers = [(comp, _find_l(comp)) for comp in comps]
    markers = [(comp, pose) for comp, pose in markers if pose]
    if not markers:
        return out
    marker, (pr, pc, vr, hc) = max(markers, key=lambda item: len(item[0][1]))
    color = marker[0]
    other = [comp for comp in comps if comp is not marker]
    pairs = []
    for i in range(len(other)):
        for j in range(i+1, len(other)):
            if _canonical(other[i][1]) == _canonical(other[j][1]):
                pairs.append((other[i], other[j]))
    if pairs:
        pair = max(pairs, key=lambda pair: len(pair[0][1]) + len(pair[1][1]))
        def open_score(comp):
            cy = sum(r for r, c in comp[1]) / len(comp[1])
            cx = sum(c for r, c in comp[1]) / len(comp[1])
            return (1 if (cy-pr) * (-vr) > 0 else 0) + (1 if (cx-pc) * (-hc) > 0 else 0)
        target = max(pair, key=open_score)
    else:
        # When there is no repeated shape, the largest separate object is the marked one.
        target = max(other, key=lambda comp: len(comp[1])) if other else None
    if target:
        for r, c in target[1]:
            out[r][c] = color
    return out
'''
